command:
const [dowsingRod, relevantActor] = await (async ()=>{
  let rActor = (await fromUuid(context?.message?.flags?.ptu?.origin?.actor)) ?? (await fromUuid(context?.message?.flags?.ptu?.origin?.item))?.actor ?? actor;
  let rItem = (await fromUuid(context?.message?.flags?.ptu?.origin?.item)) ?? actor.items.contents.find(i=>i.system.slug === "dowsing-rod" || i.name.includes("Dowsing Rod"));
  return [rItem, rActor];
})();
if (!relevantActor || !dowsingRod) {
  ui.notifications.error("No relevant actor with a Dowsing Rod found. Please select the actor that is dowsing.");
  return;
}

const useCount = dowsingRod?.flags?.ptu?.used ?? 0;
const occultEdRank = relevantActor.system.skills.occultEd.value.total;

if (useCount >= Math.floor(occultEdRank / 2)) {
  ui.notifications.warn("You have already used the Dowsing Rod the maximum number of times for today.");
  return;
}

const sand = (await foundry.applications.api.DialogV2.confirm({
    window: { title: "Dowsing Rod" },
    content: "Is this area a sandy or rocky area (beach, desert, cave, mountain, etc.)?",
})) ? 1 : 0;
const book = relevantActor.items.contents.some(i=>["dowsing-for-dummies-5-15-playtest", "dowsing-for-dummies"].includes(i?.system?.slug)) ?? false;
const forceShardColor = (book && occultEdRank >= 4 && useCount < Math.floor(occultEdRank / 2) - 1) ? (await foundry.applications.api.DialogV2.wait({
  window: { title: "Force Shard Color" },
  content: "Do you want to force the color of the Shards you find for an additional use?",
  buttons: [
    { action: "no", label: "No", icon: "fas fa-times", callback: () => "", default: true },
    { action: "red", label: "Red", callback: () => "Compendium.ptu.items.Item.mIdhpWktLBSqBT1H" },
    { action: "blue", label: "Blue", callback: () => "Compendium.ptu.items.Item.w6eiB1WS68v4Tp9y" },
    { action: "green", label: "Green", callback: () => "Compendium.ptu.items.Item.ASttzswAilKpkQ2q" },
    { action: "yellow", label: "Yellow", callback: () => "Compendium.ptu.items.Item.EMsXttzmVktkjdUn" },
    { action: "orange", label: "Orange", callback: () => "Compendium.ptu.items.Item.mvL2ySkR2aNfCsz0" },
    { action: "violet", label: "Violet", callback: () => "Compendium.ptu.items.Item.BQtWlxuEgye0Xi1X" }
  ]
})): "";
const stunt = relevantActor._itemTypes.edge.some(e => e.name.includes("Dowsing")); //searches for an edge with Dowsing in it - meant for the skill stunt
const resonance = 3 * relevantActor._itemTypes.feat.some(e => e.name.includes("Crystal Resonance"));

let roll = await new Roll(`${occultEdRank+sand+stunt+resonance+book}d6x=6cs>=4`).roll();
await roll.toMessage();

let shards = [];
if (!forceShardColor) {
  let table = game.tables.getName("Shards") || await fromUuid("Compendium.ptu.rolltables.RollTable.ddYBtN5sIfEAku9l");
  shards = (await table.drawMany(roll.total,{displayChat:true}))?.results?.map(r=>r.documentUuid);
} else {
  shards = Array.from({length: roll.total}).map(()=>forceShardColor);
}
// count up each shard type
let shardCounts = shards.reduce((acc, shard) => {
  acc[shard] = (acc[shard] || 0) + 1;
  return acc;
}, {});
for (const [shard, count] of Object.entries(shardCounts)) {
  let existingItem = relevantActor.items.contents.find(i => i._stats?.compendiumSource === shard);
  if (existingItem) {
    // Update the quantity of the existing item
    const newQuantity = (existingItem.system.quantity ?? 0) + count;
    await existingItem.update({ "system.quantity": newQuantity });
  } else {
    // Create a new item for the shard
    const shardItem = await fromUuid(shard);
    if (shardItem) {
      const itemData = foundry.utils.deepClone(shardItem.toObject());
      itemData.system.quantity = count;
      itemData._stats.compendiumSource = shard;
      await relevantActor.createEmbeddedDocuments("Item", [itemData]);
    }
  }
}
// let's figure out if this was used from a chat message while the dowsing rod itself had a frequency set
let alreadyExpended = 0;
if (dowsingRod.system.frequency.type === "daily" && context?.message && !context.message.flags?.ptu?.dowsingMacroAlreadyRun) {
  alreadyExpended = 1;
  await context.message.update({"flags.ptu.dowsingMacroAlreadyRun": true});
}
// let's decrement the usage on the dowsing rod
const newUses = (useCount ?? 0) + 1 + (forceShardColor ? 1 : 0) - alreadyExpended;
await dowsingRod.update({ 
  system: {
    frequency: {
      type: "daily",
      max: Math.floor(occultEdRank / 2)
    }
  },
  flags: {
    ptu: {
      used: newUses
    }
  }
});
